<?php

require_once __DIR__ . '/db.php';

function e(?string $value): string
{
    return htmlspecialchars($value ?? '', ENT_QUOTES, 'UTF-8');
}

/*
 * Application-wide CSRF protection.
 *
 * Every authenticated state-changing request should include the
 * token generated by csrf_field() and validate it with verify_csrf().
 */
function csrf_token(): string
{
    if (empty($_SESSION['csrf_token'])) {
        $_SESSION['csrf_token'] = bin2hex(
            random_bytes(32)
        );
    }

    return (string) $_SESSION['csrf_token'];
}

function csrf_field(): string
{
    return '<input type="hidden" name="_csrf" value="'
        . e(csrf_token())
        . '">';
}

function verify_csrf(?string $token): void
{
    $expected = csrf_token();

    if (
        !$token
        || !hash_equals(
            $expected,
            $token
        )
    ) {
        http_response_code(403);

        exit(
            'Invalid request token. Please return to WorkReport and try again.'
        );
    }
}


function redirect(string $url): never
{
    header('Location: ' . $url);
    exit;
}

function flash(string $type, string $message): void
{
    $_SESSION['flash'] = [
        'type' => $type,
        'message' => $message
    ];
}

function display_flash(): void
{
    if (empty($_SESSION['flash'])) {
        return;
    }

    $flash = $_SESSION['flash'];

    unset($_SESSION['flash']);

    echo '<div class="flash flash-' . e($flash['type']) . '">';
    echo e($flash['message']);
    echo '</div>';
}

function format_date(string $date): string
{
    $timestamp = strtotime($date);

    if (!$timestamp) {
        return $date;
    }

    return date('F j, Y', $timestamp);
}

function format_datetime(?string $date): string
{
    if (!$date) {
        return '';
    }

    $timestamp = strtotime($date);

    if (!$timestamp) {
        return $date;
    }

    return date('F j, Y g:i A', $timestamp);
}


function report_hash(array $report): string
{
    $data = implode('|', [
        $report['id'] ?? '',
        $report['report_date'] ?? '',
        $report['shift'] ?? '',
        $report['department'] ?? '',
        $report['machine'] ?? '',
        $report['title'] ?? '',
        $report['original_text'] ?? ''
    ]);

    return hash('sha256', $data);
}
